input.command:
cd "C:/Users/vamsh/.claude/projects/D--Personal-Projects-TUM-HackathonFinal" && ls -la --time-style=+%H:%M:%S 01a592eb*.jsonl && date +%H:%M:%S && python - <<'EOF'
import json,io
p="01a592eb-56f9-4511-a050-63e8a3a9c686.jsonl"
rows=[]
for line in io.open(p,encoding="utf-8",errors="replace"):
    try: d=json.loads(line)
    except Exception: continue
    t=d.get("type"); ts=d.get("timestamp","")[11:19]
    m=d.get("message") or {}
    c=m.get("content")
    if t=="user":
        if isinstance(c,str): rows.append((ts,"USER",c[:1500]))
        elif isinstance(c,list):
            for b in c:
                if b.get("type")=="text": rows.append((ts,"USER",b["text"][:1500]))
    elif t=="assistant" and isinstance(c,list):
        for b in c:
            if b.get("type")=="text" and b["text"].strip(): rows.append((ts,"ASSIST",b["text"][:1200]))
            elif b.get("type")=="tool_use":
                inp=b.get("input",{})
                s=inp.get("description") or inp.get("file_path") or inp.get("command") or inp.get("pattern") or json.dumps(inp)[:150]
                rows.append((ts,"TOOL "+b.get("name",""),str(s)[:160]))
print(len(rows))
for r in rows[:6]: print(r[0],r[1],"|",r[2].replace("\n"," ⏎ ")[:1500]); print()
print("......")
for r in rows[-45:]: print(r[0],r[1],"|",r[2].replace("\n"," ⏎ ")[:700])
EOF

