import json,io
p="01a592eb-56f9-4511-a050-63e8a3a9c686.jsonl"
ids={}
out=[]
for line in io.open(p,encoding="utf-8",errors="replace"):
    try: d=json.loads(line)
    except Exception: continue
    t=d.get("type"); ts=d.get("timestamp","")[11:19]
    m=d.get("message") or {}
    c=m.get("content")
