                if b.get("name")=="Write":
                    print("WRITE",ts,b["input"].get("file_path"),len(b["input"].get("content","")),"chars")
                    print(b["input"].get("content","")[:3500]); print("=====")
                if b.get("name")=="Bash" and ("Record decision" in str(b["input"].get("description")) or "Probe Qwen" in str(b["input"].get("description"))):
                    print("BASH",ts,b["input"].get("description")); print(b["input"].get("command","")[:2500]); print("-----")
    if t=="user" and isinstance(c,list):
        for b in c:
            if b.get("type")=="tool_result":
                tid=b.get("tool_use_id")
                if tid in ids and ids[tid][1]=="Bash" and ("Probe Qwen" in str(ids[tid][2].get("description")) ):
                    cc=b.get("content")
                    txt=cc if isinstance(cc,str) else " ".join(x.get("text","") for x in cc if isinstance(x,dict))
                    print("RESULT of",ids[tid][2].get("description")); print(txt[:4000]); print("-----")
EOF

