304	    def _on_response(self, response):
305	        try:
306	            if response.request.is_navigation_request() and response.frame == self.page.main_frame:
307	                self.bad_status = response.status if response.status >= 500 else 0
308	        except Exception:  # noqa: BLE001
309	            pass
