311	    async def settle(self):
312	        for state, timeout in (("domcontentloaded", 15000), ("networkidle", 2500)):
313	            try:
314	                await self.page.wait_for_load_state(state, timeout=timeout)
315	            except Exception:  # noqa: BLE001
316	                pass
317	        for _ in range(3):  # a server error page: retry the same address, as a person would press reload
318	            if not self.bad_status:
