320	            self.events.append(f"the server answered HTTP {self.bad_status}; reloaded")
321	            await asyncio.sleep(0.4)
322	            try:
323	                await self.page.reload(wait_until="domcontentloaded", timeout=15000)
324	            except Exception:  # noqa: BLE001
